diff --git a/src/functionalTest/kotlin/com/github/jengelman/gradle/plugins/shadow/JavaPluginsTest.kt b/src/functionalTest/kotlin/com/github/jengelman/gradle/plugins/shadow/JavaPluginsTest.kt
index d2c17cac..91593960 100644
--- a/src/functionalTest/kotlin/com/github/jengelman/gradle/plugins/shadow/JavaPluginsTest.kt
+++ b/src/functionalTest/kotlin/com/github/jengelman/gradle/plugins/shadow/JavaPluginsTest.kt
@@ -191,6 +191,53 @@ class JavaPluginsTest : BasePluginTest() {
     }
   }

+  @Issue(
+    "https://github.com/GradleUp/shadow/issues/1606",
+  )
+  @Test
+  fun shadowExposedCustomSourceSetOutput() {
+    writeClientAndServerModules()
+    path("client/build.gradle").appendText(
+      """
+        sourceSets {
+          custom
+        }
+        dependencies {
+          implementation sourceSets.custom.output
+        }
+      """.trimIndent(),
+    )
+    path("client/src/custom/java/client/Custom1.java").writeText(
+      """
+        package client;
+        public class Custom1 {}
+      """.trimIndent(),
+    )
+    path("client/src/custom/java/client/Custom2.java").writeText(
+      """
+        package client;
+        public class Custom2 {}
+      """.trimIndent(),
+    )
+    path("client/src/custom/resources/Foo.bar").writeText("Foo=Bar")
+
+    run(serverShadowJarPath)
+
+    assertThat(outputServerShadowedJar).useAll {
+      containsOnly(
+        "Foo.bar",
+        "client/",
+        "server/",
+        "client/Client.class",
+        "client/Custom1.class",
+        "client/Custom2.class",
+        "server/Server.class",
+        *junitEntries,
+        *manifestEntries,
+      )
+    }
+  }
+
   @Issue(
     "https://github.com/GradleUp/shadow/issues/449",
   )
